Idiomatic review of a Go handler:

func (s *Server) Handle(w http.ResponseWriter, r *http.Request) {
    body, err := io.ReadAll(r.Body)
    if err != nil { s.log.Error(err); return }
    if data, err := s.parse(body); err != nil {
        http.Error(w, fmt.Errorf("Parsing failed.").Error(), 400)
        return
    } else { s.store(data) }
}

